6	/**
7	 * Per-role browser perspectives — ADR 0033 slice #743.
8	 *
9	 * The dev-bypass identity is always a workspace admin (#741) and cannot be
10	 * demoted, so a browser cannot experience the other two tiers as itself. These
11	 * specs instead authenticate as REAL seeded users via a PAT: `get_current_user`
12	 * resolves a `dq_live_` bearer *before* the dev-bypass branch, so a context that
13	 * sets an Authorization header is that user for every request the Vite proxy
14	 * forwards.
15	 *
16	 * That matters more than the convenience. Mocking `/me` to claim a role would
17	 * test the UI against a lie — it could not catch a control that is hidden
18	 * correctly but whose endpoint is ungated, nor a page that 403s for a tier the
19	 * UI happily renders. Here the server genuinely is deciding.
20	 *
21	 * Tokens come from `python -m backend.scripts.seed_dev`, which writes them to a
22	 * gitignored file; CI seeds before Playwright runs. If the file is missing the
23	 * specs SKIP with an explanatory message rather than failing — a missing seed is
24	 * an environment problem, and a red suite that means "you forgot to seed" trains
25	 * people to ignore red suites.
26	 */
27	
28	type Role = 'member' | 'viewer';
29	
30	const TOKENS_PATH = fileURLToPath(new URL('./.role-tokens.json', import.meta.url));
31	
32	function tokens(): Record<Role, string> | null {
33	  try {
34	    return JSON.parse(readFileSync(TOKENS_PATH, 'utf8')) as Record<Role, string>;
35	  } catch {
36	    return null;
37	  }
38	}
39	
40	const ROLE_TOKENS = tokens();
41	
